import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.e4u2V5E7.js";const m=JSON.parse('{"title":"Css","description":"Css reference documentation","frontmatter":{"title":"Css","description":"Css reference documentation"},"headers":[],"relativePath":"knowledge/css.md","filePath":"knowledge/css.md","lastUpdated":1784485118000}'),r={name:"knowledge/css.md"};function n(s,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="css" tabindex="-1">Css <a class="header-anchor" href="#css" aria-label="Permalink to &quot;Css&quot;">​</a></h1><h1 id="modern-css-—-knowledge-reference" tabindex="-1">Modern CSS — Knowledge Reference <a class="header-anchor" href="#modern-css-—-knowledge-reference" aria-label="Permalink to &quot;Modern CSS — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Reference for modern CSS features covering layout systems, custom properties, container queries, the <code>:has()</code> selector, logical properties, animations, layers, color functions, calc functions, and specificity management. Focused on production-quality CSS for scalable applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="css-grid" tabindex="-1">CSS Grid <a class="header-anchor" href="#css-grid" aria-label="Permalink to &quot;CSS Grid&quot;">​</a></h3><p>Two-dimensional layout system. Define rows and columns with <code>grid-template-columns</code> and <code>grid-template-rows</code>. Place items with <code>grid-column</code> and <code>grid-row</code>. Use <code>fr</code> units for flexible sizing. <code>grid-auto-flow</code> controls implicit placement. Named grid areas via <code>grid-template-areas</code> for readable layouts.</p><h3 id="flexbox" tabindex="-1">Flexbox <a class="header-anchor" href="#flexbox" aria-label="Permalink to &quot;Flexbox&quot;">​</a></h3><p>One-dimensional layout system for rows or columns. <code>display: flex</code> enables flex context. <code>justify-content</code> aligns along main axis, <code>align-items</code> along cross axis. <code>flex-wrap</code> enables multi-line. <code>flex-grow</code>, <code>flex-shrink</code>, <code>flex-basis</code> control sizing. <code>gap</code> provides consistent spacing.</p><h3 id="css-custom-properties" tabindex="-1">CSS Custom Properties <a class="header-anchor" href="#css-custom-properties" aria-label="Permalink to &quot;CSS Custom Properties&quot;">​</a></h3><p>Variables defined with <code>--property: value</code> and accessed with <code>var(--property)</code>. Cascade-aware: values inherit and can be overridden at any level. Enable dynamic theming, responsive values, and component-level customization. Fallback values: <code>var(--color, blue)</code>.</p><h3 id="container-queries" tabindex="-1">Container Queries <a class="header-anchor" href="#container-queries" aria-label="Permalink to &quot;Container Queries&quot;">​</a></h3><p>Style elements based on their container&#39;s size, not the viewport. <code>@container (min-width: 700px) { ... }</code> queries the nearest containment context. Define containment with <code>container-type: inline-size</code> on the parent. Enable truly reusable responsive components.</p><h3 id="has-selector" tabindex="-1">:has() Selector <a class="header-anchor" href="#has-selector" aria-label="Permalink to &quot;:has() Selector&quot;">​</a></h3><p>Parent selector: <code>.card:has(img) { ... }</code> styles <code>.card</code> only when it contains an <code>img</code>. Also works for sibling selection: <code>label:has(+ input:checked)</code>. Enables complex selector patterns previously impossible with CSS alone.</p><h3 id="logical-properties" tabindex="-1">Logical Properties <a class="header-anchor" href="#logical-properties" aria-label="Permalink to &quot;Logical Properties&quot;">​</a></h3><p>Direction-agnostic properties that respect <code>direction</code> and <code>writing-mode</code>. <code>margin-inline-start</code> replaces <code>margin-left</code> (for LTR). <code>padding-block</code> replaces <code>padding-top</code>/<code>padding-bottom</code>. Essential for internationalization and RTL support.</p><h3 id="css-animations" tabindex="-1">CSS Animations <a class="header-anchor" href="#css-animations" aria-label="Permalink to &quot;CSS Animations&quot;">​</a></h3><p><code>@keyframes</code> define animation sequences. <code>animation</code> shorthand combines name, duration, timing, delay, iteration, direction, fill-mode, and play-state. <code>transition</code> animates between two states. <code>transform</code> enables GPU-accelerated animations: <code>translate</code>, <code>rotate</code>, <code>scale</code>.</p><h3 id="layer" tabindex="-1">@layer <a class="header-anchor" href="#layer" aria-label="Permalink to &quot;@layer&quot;">​</a></h3><p>Cascade layers control specificity order. <code>@layer base, components, utilities;</code> declares layer order. Unlayered styles always win. Enables Tailwind-style utility overrides and third-party style isolation.</p><h3 id="color-mix" tabindex="-1">color-mix() <a class="header-anchor" href="#color-mix" aria-label="Permalink to &quot;color-mix()&quot;">​</a></h3><p>CSS function for mixing colors: <code>color-mix(in srgb, red 50%, blue 50%)</code>. Supports any color space: <code>in oklch</code>, <code>in oklab</code>, <code>in hsl</code>. Enables dynamic color variations without pre-defining every shade.</p><h3 id="calc-and-clamp" tabindex="-1">calc() and clamp() <a class="header-anchor" href="#calc-and-clamp" aria-label="Permalink to &quot;calc() and clamp()&quot;">​</a></h3><p><code>calc()</code> performs math in CSS: <code>width: calc(100% - 2rem)</code>. <code>clamp()</code> constrains a value between min and max: <code>font-size: clamp(1rem, 2.5vw, 2rem)</code>. <code>min()</code>, <code>max()</code>, <code>minmax()</code> provide additional value constraint functions.</p><h3 id="specificity" tabindex="-1">Specificity <a class="header-anchor" href="#specificity" aria-label="Permalink to &quot;Specificity&quot;">​</a></h3><p>CSS specificity determines which rule wins: inline styles (1000) &gt; IDs (100) &gt; classes/attributes/pseudo-classes (10) &gt; elements/pseudo-elements (1). <code>!important</code> overrides all specificity. Use <code>@layer</code> to manage specificity hierarchically.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use CSS Grid for page layout, Flexbox for component layout</strong> — Grid excels at two-dimensional alignment; Flexbox excels at one-dimensional distribution</li><li><strong>Define design tokens as custom properties on <code>:root</code></strong> — colors, spacing, typography, and shadows should be themeable CSS variables</li><li><strong>Use logical properties for internationalization</strong> — <code>margin-inline-start</code> instead of <code>margin-left</code> enables automatic RTL support</li><li><strong>Implement container queries for reusable components</strong> — components that respond to their container, not the viewport, are truly portable</li><li><strong>Use <code>clamp()</code> for fluid typography</strong> — <code>font-size: clamp(1rem, 0.5rem + 1vw, 2rem)</code> scales smoothly without breakpoints</li><li><strong>Leverage <code>:has()</code> for complex parent/sibling selectors</strong> — reduces JavaScript for conditional styling; cleaner than <code>~</code> sibling combinators</li><li><strong>Use <code>@layer</code> to manage specificity</strong> — separate base, components, and utilities into layers to prevent specificity wars</li><li><strong>Prefer <code>color-mix()</code> over pre-defined color scales</strong> — generates exact shades dynamically: <code>color-mix(in oklch, var(--primary), white 20%)</code></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>!important</code> as a fix for specificity issues</strong> — <code>!important</code> creates cascading problems; fix the specificity hierarchy instead</li><li><strong>Hardcoded pixel values for everything</strong> — use relative units (<code>rem</code>, <code>em</code>, <code>%</code>, <code>vw</code>, <code>vh</code>) for accessibility and responsiveness</li><li><strong>Overriding specificity with deeper selectors</strong> — <code>.sidebar .nav .link .active { ... }</code> is fragile; use BEM or utility classes</li><li><strong>Ignoring <code>prefers-reduced-motion</code></strong> — always respect user motion preferences: <code>@media (prefers-reduced-motion: reduce) { animation: none; }</code></li><li><strong>Using <code>position: absolute</code> for layout</strong> — absolute positioning removes elements from flow; prefer Grid/Flexbox for layout</li><li><strong>Writing vendor prefixes manually</strong> — use Autoprefixer; it adds only the prefixes needed based on your browser support targets</li><li><strong>Not using <code>box-sizing: border-box</code></strong> — content-box sizing makes width calculations unreliable; use <code>border-box</code> universally</li><li><strong>Ignoring browser support for new features</strong> — check caniuse.com; use <code>@supports</code> queries as progressive enhancement</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Confusing <code>em</code> and <code>rem</code></strong> — <code>em</code> is relative to parent font-size; <code>rem</code> is relative to root font-size; use <code>rem</code> for consistent sizing</li><li><strong>Not understanding the box model</strong> — <code>width</code> includes padding and border only with <code>box-sizing: border-box</code></li><li><strong>Using <code>min-height</code> without explicit <code>height</code></strong> — <code>min-height</code> does not work without <code>height</code> in flexbox; pair with <code>flex: 1</code></li><li><strong>Forgetting <code>z-index</code> requires positioning</strong> — <code>z-index</code> only works on positioned elements (<code>relative</code>, <code>absolute</code>, <code>fixed</code>, <code>sticky</code>)</li><li><strong>Using <code>overflow: hidden</code> to clear floats</strong> — use <code>clearfix</code> or, better, modern layout systems (Flexbox/Grid)</li><li><strong>Not understanding stacking context</strong> — <code>z-index</code> is local to stacking context; a <code>z-index: 9999</code> inside a <code>z-index: 1</code> parent is still below <code>z-index: 2</code></li><li><strong>Using <code>margin: 0 auto</code> for vertical centering</strong> — horizontal centering only; use Flexbox/Grid for both axes</li><li><strong>Ignoring paint and layout performance</strong> — animate only <code>transform</code> and <code>opacity</code>; avoid animating <code>width</code>, <code>height</code>, <code>top</code>, <code>left</code></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>Page-level layout</td><td>CSS Grid with <code>grid-template-areas</code></td></tr><tr><td>Navigation bar</td><td>Flexbox</td></tr><tr><td>Card component</td><td>Container queries + Grid or Flexbox</td></tr><tr><td>Fluid typography</td><td><code>clamp(1rem, 0.5rem + 1vw, 2rem)</code></td></tr><tr><td>RTL support</td><td>Logical properties</td></tr><tr><td>Dynamic color variations</td><td><code>color-mix()</code></td></tr><tr><td>Animations</td><td><code>transition</code> for state changes, <code>@keyframes</code> for sequences</td></tr><tr><td>Style isolation</td><td><code>@layer</code></td></tr><tr><td>Parent-dependent styling</td><td><code>:has()</code></td></tr><tr><td>Responsive images</td><td><code>&lt;picture&gt;</code> + <code>srcset</code> + CSS <code>object-fit</code></td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/CSS" target="_blank" rel="noreferrer">MDN CSS Reference</a></li><li><a href="https://css-tricks.com" target="_blank" rel="noreferrer">CSS-Tricks</a></li><li><a href="https://caniuse.com" target="_blank" rel="noreferrer">Can I Use</a></li><li><a href="https://web.dev/learn/css" target="_blank" rel="noreferrer">Web.dev CSS Features</a></li><li><a href="https://every-layout.dev" target="_blank" rel="noreferrer">Every Layout</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>color-mix()</code> is supported in all modern browsers (2023+); use <code>@supports</code> for graceful degradation</li><li>Container queries have excellent support but require <code>container-type: inline-size</code> on the parent element</li><li><code>:has()</code> is supported in Chrome 105+, Safari 15.4+, Firefox 121+; excellent support as of 2025</li><li>CSS nesting is now natively supported in modern browsers; reduces the need for preprocessors</li><li>Use <code>@property</code> to define custom properties with types, initial values, and inheritance; enables animated custom properties</li><li><code>scroll-timeline</code> and <code>view-timeline</code> enable scroll-driven animations without JavaScript</li><li>The CSS <code>has</code> selector is the most powerful addition to CSS since Flexbox; learn it thoroughly</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',41)])])}const u=o(r,[["render",n]]);export{m as __pageData,u as default};
